// Généré par `npm run templates:build` depuis content/templates et packages/interpreter/conformance — ne pas modifier à la main.
export const corpus: readonly { name: string; origin: "installed" | "canonical"; yaml: string }[] = [
  {
    "name": "code",
    "origin": "installed",
    "yaml": "# The code flow as a template (template parity P3).\n#\n# Reconciled with the hand-written flow (content/flows/code), which stays in the\n# tree as the equivalence reference:\n# - a participant (or a group, through its holder) delivers on a workspace: a\n#   branch provisioned on the challenge repo (provided_repo) or their own public\n#   GitHub repository declared with PATCH workspace (own_repo);\n# - the evaluation waits for a board with at least one task, every task done;\n# - it runs in the background, one at a time, on the holder's `project`\n#   contribution, graded by the `code` grid on the branch's recent history;\n# - pay is `fixed` then `cap × score / 10`, both multiplied by the group bonus,\n#   paid as a delta over what each rule already paid, clamped to the pool;\n#   a group's delta is split between its members;\n# - the ledger keys are `code_fixed` and `code_quality`; a failed run replays\n#   under the `project` handler, legacy runs included.\n\nformat: leaderboardos/1\n\ntemplate:\n  id: code\n  version: 1.0.0\n  name: Code\n  summary: >\n    Each participant or group delivers a project on a personal branch or their\n    own repository, evaluated by the code grid once their board is done, and is\n    paid the improvement of each evaluation from the pool.\n\nparams:\n  pool:           {type: points, mutable: false}\n  workspace_mode: {type: \"enum(provided_repo, own_repo)\", default: provided_repo, mutable: false}\n  # The rules keep the code flow's stored shape: {version: 1, delivery: {fixed, cap}}.\n  version:        {type: int, default: 1, check: \"value == 1\", mutable: true}\n  delivery:       {type: {fixed: points, cap: points}, mutable: true}\n\nrequires: {core: 1}\n\npresentation:\n  icon: code\n  long_label: Code\n  join_caption: \"Joining copies the template tasks onto your board and provisions your branch.\"\n  brief_required: true\n  public: true\n  board: true\n  evaluation_handler: project\n  contribution:\n    type: project\n    title: Project delivery\n    description: '\"Global delivery for \\\"\" + challenge.title + \"\\\"\"'\n    deliverables: [deployed_app]\n\nworkspace:\n  mode: params.workspace_mode\n\nlanes:\n  - id: project_evaluation\n    entry: {trigger: user, access: {mode: open, group: true}}\n    nodes:\n      - gate: {id: open, all: ['challenge.state == \"open\"'], refuse: 400, message: Cannot start evaluation, reason: challenge_closed}\n      - gate: {id: workspace_ready, all: [participation.workspace.ready], refuse: 400, message: Cannot start evaluation, reason: workspace_not_ready}\n      - gate: {id: has_tasks, all: [\"board.total > 0\"], refuse: 400, message: Cannot start evaluation, reason: no_tasks}\n      - gate: {id: board_done, all: [\"board.done == board.total\"], refuse: 400, message: Cannot start evaluation, reason: tasks_not_done}\n      - assess:\n          id: grade\n          kind: ai_grid\n          grid: '\"code\"'\n          input: [participation.workspace.url]\n          snapshot: history\n          background: true\n      - reward:\n          id: fixed\n          rule_key: code_fixed\n          amount: \"params.delivery.fixed * participation.group.multiplier\"\n          basis: delta\n          pool: params.pool\n          clamp: pool\n          meta: {agentScore: \"grade.score * 10\"}\n      - reward:\n          id: quality\n          rule_key: code_quality\n          amount: \"params.delivery.cap * (grade.score * 10) * participation.group.multiplier / 10\"\n          basis: delta\n          pool: params.pool\n          clamp: pool\n          meta: {agentScore: \"grade.score * 10\"}\n"
  },
  {
    "name": "data-annotation",
    "origin": "installed",
    "yaml": "# The data-annotation flow as a template (interpreter J3).\n#\n# Reconciled with the hand-written flow (content/flows/data-annotation), which\n# wins wherever the conformance suite §6 diverged:\n# - params carry the flow's names and split: k, ttl_hours, label_schema and\n#   sensitive_clearance are fixed at creation; per_unit_cp, gold_rate and\n#   audit_rate are the editable reward rules;\n# - an item without a strict plurality closes as `contested`;\n# - accuracy lags the ten most recent labels, so a score change never points\n#   at the gold that caused it;\n# - golds are claimed once per annotator, with the same TTL as items;\n# - the audit visits each labeled item once and reverses exactly what a\n#   disagreeing label was paid, net of earlier clawbacks;\n# - the ledger keys are `annotation` and `annotation_clawback`;\n# - an admin settles a contested item by hand (the resolve lane).\n#\n# release, progress, overview and export are not written here: the compiler\n# generates them (design note, trade-off 10).\n\nformat: leaderboardos/1\n\ntemplate:\n  id: data-annotation\n  version: 1.0.0\n  name: Annotation\n  summary: >\n    Annotators label items under k-redundancy; hidden gold cases maintain a\n    lagged accuracy that weights pay and gates sensitive items; items resolve\n    by strict plurality; payment is fast, audited by sampled clawback.\n\nparams:\n  pool:        {type: points, mutable: false}\n  k:           {type: int, default: 3, check: \"value >= 1 && value <= 15 && value % 2 == 1\", mutable: false}\n  ttl_hours:   {type: int, default: 48, check: \"value >= 1 && value <= 720\", mutable: false}\n  label_schema:\n    type: \"{kind: enum(single_choice), options: list({key: string, label: string})}\"\n    checks:\n      between_2_and_12_options: \"size(value.options) >= 2 && size(value.options) <= 12\"\n      options_need_a_key_and_a_label: \"value.options.all(o, size(o.key) > 0 && size(o.label) > 0)\"\n      option_keys_must_be_unique: \"value.options.all(o, size(value.options.filter(p, p.key == o.key)) == 1)\"\n    mutable: false\n  sensitive_clearance:\n    type: {min_seen: int, min_accuracy: ratio}\n    default: {min_seen: 5, min_accuracy: 0.8}\n    mutable: false\n  per_unit_cp: {type: points, check: \"value >= 0\", mutable: true}\n  gold_rate:   {type: ratio, default: 0.1, check: \"value >= 0.0 && value <= 1.0\", mutable: true}\n  audit_rate:  {type: ratio, default: 0.1, check: \"value >= 0.0 && value <= 1.0\", mutable: true}\n\nrequires: {core: 1}\n\npresentation:\n  icon: tag\n  long_label: Data annotation\n  join_caption: \"Joining lets you label items one at a time; your pay follows your quality score.\"\n  brief_required: true\n  public: true\n  contribution: {type: annotation, title: Annotations}\n\nresources:\n  item:\n    fields:\n      image_url: {type: url, visibility: [claimant, admin]}\n      class:     {type: \"enum(standard, sensitive)\", visibility: [admin]}\n    created_by: [import.explode_items]\n    claim: {mode: k_bounded, k: params.k, ttl: params.ttl_hours}\n    closure: {by: [aggregate, admin_act], verdict: [labeled, contested]}\n  gold:\n    fields:\n      image_url: {type: url, visibility: [claimant, admin]}\n      expected:  {type: string, visibility: [], check: \"params.label_schema.options.exists(o, o.key == value)\"}\n    created_by: [import.explode_golds]\n    claim: {mode: unique_per, dimensions: [self, participation], ttl: params.ttl_hours}\n\ncounters:\n  gold_seen:    {type: int, lag: 10}\n  gold_correct: {type: int, lag: 10}\n\nlifecycle:\n  aggregates:\n    - id: agreement\n      over: item\n      per_participation: 1\n      resolve:\n        when:    \"count(inputs) >= params.k\"\n        verdict: \"mode(inputs.map(i, i.value))\"\n        then:\n          - transition: {resource: item, to: closed, verdict: 'verdict == null ? \"contested\" : \"labeled\"'}\n\nlanes:\n  - id: import\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: batch\n          fields:\n            file:  {type: json}\n            kind:  {type: \"enum(items, golds)\"}\n            class: {type: \"enum(standard, sensitive)\", when: 'kind == \"items\"'}\n      - gate:\n          id: kind\n          branch:\n            - when: 'batch.kind == \"golds\"'\n              nodes:\n                - act: {id: explode_golds, create: gold, many: {from_file: batch.file}}\n            - else:\n                nodes:\n                  - act: {id: explode_items, create: item, many: {from_file: batch.file}, set: {class: batch.class}}\n\n  - id: resolve\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: decide\n          fields:\n            item:  {type: \"ref(item)\"}\n            value: {type: string, check: \"params.label_schema.options.exists(o, o.key == value)\"}\n      - act:\n          id: settle\n          transition:\n            resource: decide.item\n            to: closed\n            from: contested\n            verdict: labeled\n            resolution: {consensus: decide.value, resolved_by: participation.user, resolved_at: now()}\n\n  - id: annotator\n    entry: {trigger: user, access: {mode: open}}\n    nodes:\n      - gate: {id: open, all: ['challenge.state == \"open\"']}\n      - act:\n          id: draw\n          claim:\n            resource: item\n            where: >\n              item.class == \"standard\"\n              || (counters.gold_seen >= params.sensitive_clearance.min_seen\n                  && (counters.gold_seen > 0 ? counters.gold_correct * 1.0 / counters.gold_seen : 0.0)\n                     >= params.sensitive_clearance.min_accuracy)\n            substitute: {resource: gold, rate: params.gold_rate}\n      - collect:\n          id: label\n          fields:\n            value: {type: string, check: \"params.label_schema.options.exists(o, o.key == value)\"}\n      - gate:\n          id: kind\n          branch:\n            - when: \"draw.substituted\"\n              nodes:\n                - assess:\n                    id: check\n                    kind: metric\n                    value: \"label.value == draw.gold.expected\"\n                    counters:\n                      gold_seen:    {add: \"1\"}\n                      gold_correct: {add: \"value ? 1 : 0\"}\n            - else:\n                nodes:\n                  - assess:\n                      id: submit\n                      kind: human\n                      from: label\n                      emit: {to: lifecycle.agreement, scope: draw.item}\n      - reward:\n          id: pay\n          rule_key: annotation\n          amount: >\n            params.per_unit_cp\n            * (counters.gold_seen == 0 ? 1.0\n               : counters.gold_correct * 1.0 / counters.gold_seen)\n          pool: params.pool\n          clamp: pool\n\n  - id: audit\n    entry:\n      trigger: cron\n      schedule: \"0 4 * * 1\"\n      over: {resource: item, where: 'item.closed && item.verdict == \"labeled\"', sample: params.audit_rate}\n      cursor: engine\n    nodes:\n      - assess:\n          id: recheck\n          kind: metric\n          value: \"aggregates.agreement.inputs.filter(i, i.value != aggregates.agreement.verdict)\"\n      - reward:\n          id: clawback\n          to: recheck.value\n          amount: {reverse: annotation}\n          rule_key: annotation_clawback\n          pool: params.pool\n"
  },
  {
    "name": "endpoint-check",
    "origin": "installed",
    "yaml": "# Endpoint validation as a template (interpreter J5).\n#\n# Retired by attrition, not by handover: the hand-written flow\n# (content/flows/endpoint-validation) keeps serving the challenges that exist,\n# and this template serves new ones under its own flow key and ledger keys.\n# No data moves between them.\n#\n# Reconciled with the hand-written flow, which wins wherever the conformance\n# suite §6 diverged:\n# - params carry the flow's names: cp_per_validation, required_validations\n#   and reviewer_qualification (defaulted by the distribution);\n# - reviewers hold the qualification; an admin or a manager does not review\n#   in their place, but exposes targets;\n# - a case is claimed by calling the endpoint with it: the probe runs first,\n#   and an unreachable endpoint refuses the claim (502) without holding it;\n# - a reviewer never validates their own submission, nor claims a case they\n#   wrote (403);\n# - the observation comes before the reveal, the reveal before the verdict;\n# - at quorum the majority side is paid, earliest first, clamped to the pool;\n#   late verdicts are recorded without pay;\n# - case files and endpoint responses are kept 12 months after close.\n#\n# claim, file, options, progress, overview and export are not written here:\n# the compiler generates them (design note, trade-off 10).\n\nformat: leaderboardos/1\n\ntemplate:\n  id: endpoint-check\n  version: 1.0.0\n  name: Validation\n  summary: >\n    Qualified reviewers verify deployed submissions from a source challenge\n    against peer-authored ground-truth cases, under quorum.\n\nparams:\n  pool:                   {type: points, mutable: false}\n  cp_per_validation:      {type: points, check: \"value >= 0\", mutable: false}\n  required_validations:   {type: int, check: \"value >= 1 && value % 2 == 1\", mutable: false}\n  source_challenge:       {type: challenge_ref, mutable: false}\n  reviewer_qualification: {type: role, mutable: false}\n\nrequires: {core: 1}\n\npresentation:\n  icon: shield\n  long_label: Endpoint validation\n  brief_required: false\n  public: false\n  contribution: {type: endpoint_check, title: Validations}\n\nresources:\n  target:\n    fields:\n      contribution: {type: link, from: params.source_challenge, deliverable: endpoint, unique: true}\n      endpoint_url: {type: url, visibility: [admin, \"role(params.reviewer_qualification)\"]}\n    created_by: [admin.create_target]\n    closure: {by: aggregate, verdict: [works, broken], permanent: true}\n\n  reference_case:\n    fields:\n      input:           {type: file, visibility: [author, admin], retention: {days_after_close: 365}}\n      expected_output: {type: file, visibility: [], retention: {days_after_close: 365}}\n    created_by: [author.create_case]\n    cardinality: {exactly: params.required_validations}\n    claim:\n      mode: unique_per\n      dimensions: [self, target]\n\nlifecycle:\n  states: standard\n  aggregates:\n    - id: quorum\n      over: target\n      per_participation: 1\n      resolve:\n        when:    \"count(inputs) == params.required_validations\"\n        verdict: \"majority(inputs.map(i, i.verdict))\"\n        then:\n          - transition: {resource: target, to: closed}\n          - reward:\n              to:       \"inputs.filter(i, i.verdict == verdict)\"\n              amount:   params.cp_per_validation\n              pool:     params.pool\n              order:    commit_time\n              clamp:    pool\n              rule_key: endpoint_check\n      state_visibility:\n        count: everyone\n        split: admin\n\nlanes:\n  - id: admin\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: expose\n          fields:\n            contribution: {type: link, from: params.source_challenge, deliverable: endpoint}\n            endpoint_url: {type: url}\n      - act: {id: create_target, create: target, from: expose}\n\n  - id: author\n    entry:\n      trigger: user\n      access: {mode: role, role: params.reviewer_qualification}\n    nodes:\n      - collect:\n          id: submit_case\n          fields:\n            input:           {type: file}\n            expected_output: {type: file}\n      - act: {id: create_case, create: reference_case, from: submit_case}\n\n  - id: reviewer\n    entry:\n      trigger: user\n      access: {mode: role, role: params.reviewer_qualification}\n    nodes:\n      - collect:\n          id: pick\n          fields:\n            target: {type: \"ref(target)\", where: \"target.open\"}\n            case:   {type: \"ref(reference_case)\"}\n      - gate:\n          id: eligibility\n          refuse: 403\n          all:\n            - \"pick.case.author != participation.user\"\n            - \"pick.target.contribution.author != participation.user\"\n      - act:\n          id: probe\n          kind: observer\n          claim: {resource: pick.case, scope: {target: pick.target}}\n          capability: http_proxy\n          send:  pick.case.input\n          to:    pick.target.endpoint_url\n          retention_days: \"365\"\n          store: response\n      - collect:\n          id: observation\n          fields: {text: {type: string, check: \"size(value.trim()) > 0\"}}\n      - act:\n          id: reveal\n          kind: grant\n          grant: {field: pick.case.expected_output, to: participation}\n      - assess:\n          id: verdict\n          kind: human\n          fields:\n            verdict:     {type: \"enum(works, broken)\"}\n            description: {type: string, check: \"size(value.trim()) > 0\"}\n          emit: {to: lifecycle.quorum, scope: pick.target}\n"
  },
  {
    "name": "journey-validation",
    "origin": "installed",
    "yaml": "# Journey validation as a template (template parity P4).\n#\n# Flipped with continuity: the hand-written flow (content/flows/journey-validation)\n# stays in the tree as the equivalence reference, and the challenges it served\n# switch to this template once scripts/db-migrate-journey-resources.ts has\n# copied their data into resources (same uuids, old tables kept):\n#   validation_targets        -> app          (payload: contribution, app_url)\n#   validation_scenario_steps -> step         (position, title, instructions)\n#   validation_scenario_runs  -> walkthrough  (closed \"completed\" once finished)\n#   validation_step_feedbacks -> step_result  (result, comment, medical_comment)\n#\n# The rules of the hand-written flow, kept:\n# - managers expose deployed apps of the source challenge and write one\n#   ordered scenario, frozen as soon as any walkthrough exists (409);\n# - any signed-in account whose platform role is eligible walks through an\n#   app, never their own nor their group's (403); opening twice returns the\n#   same walkthrough, completed or not;\n# - a step result is overwritten when revisited; an expert comment needs the\n#   configured qualification (403), a blank one is always accepted;\n# - completing needs an overall feedback and a result on every step, makes\n#   the walkthrough immutable and pays cp_per_validation to the validator,\n#   clamped to the pool: nothing is resolved, nothing is paid to the author.\n#\n# options, mine, resources, progress, overview and export are generated.\n\nformat: leaderboardos/1\n\ntemplate:\n  id: journey-validation\n  version: 1.0.0\n  name: Validation\n  summary: >\n    Validators walk through the same scenario, step by step, in every deployed\n    app of a source challenge, and close on an overall feedback.\n\nparams:\n  pool:                         {type: points, mutable: false}\n  cp_per_validation:            {type: points, check: \"value > 0\", mutable: false}\n  eligible_roles:               {type: \"list(string)\", check: \"size(value) >= 1\", default: [contributor, admin], mutable: false}\n  expert_comment_qualification: {type: role, mutable: false}\n  source_challenge:             {type: challenge_ref, mutable: false}\n\nrequires: {core: 1}\n\npresentation:\n  icon: shield\n  long_label: Journey validation\n  brief_required: false\n  public: false\n  contribution:\n    type: validation\n    title: Validations performed\n    description: '\"Validations on \" + challenge.title'\n\nresources:\n  app:\n    fields:\n      contribution: {type: link, from: params.source_challenge, deliverable: deployed_app, unique: true}\n      app_url:      {type: url}\n    created_by: [apps.expose_app]\n\n  step:\n    fields:\n      position:     {type: int}\n      title:        {type: string, check: \"size(value) > 0 && size(value) <= 255\"}\n      instructions: {type: string, optional: true}\n    ordered_by: position\n    created_by: [add_step.create_step]\n\n  walkthrough:\n    fields:\n      app: {type: \"ref(app)\"}\n    created_by: [open.open_run]\n    closure: {by: transition, verdict: [completed]}\n\n  step_result:\n    fields:\n      walkthrough:     {type: \"ref(walkthrough)\"}\n      step:            {type: \"ref(step)\"}\n      result:          {type: \"enum(passed, failed, blocked)\"}\n      comment:         {type: string, optional: true, visibility: [author, admin]}\n      medical_comment: {type: string, optional: true, visibility: [author, admin]}\n    created_by: [record.save_result]\n\nlanes:\n  # ── Managers: the apps under test ──────────────────────────────────────\n  - id: apps\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: expose\n          fields:\n            contribution: {type: link, from: params.source_challenge, deliverable: deployed_app}\n            app_url:      {type: url, public: true}\n      - act: {id: expose_app, create: app, from: expose}\n\n  - id: withdraw\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: withdraw_app\n          fields:\n            app: {type: \"ref(app)\"}\n      - gate:\n          id: untouched\n          refuse: 409\n          message: Cannot remove a target that already has walkthroughs\n          all: [\"!walkthrough.exists(w, w.app.id == withdraw_app.app.id)\"]\n      - act: {id: remove_app, delete: withdraw_app.app}\n\n  # ── Managers: the scenario, frozen by the first walkthrough ───────────\n  - id: add_step\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: new_step\n          fields:\n            title:        {type: string, trim: true, check: \"size(value) > 0 && size(value) <= 255\"}\n            instructions: {type: string, trim: true, optional: true}\n      - gate:\n          id: not_frozen\n          refuse: 409\n          message: A walkthrough has already started on this challenge - the scenario is frozen\n          all: [\"size(walkthrough) == 0\"]\n      - act: {id: create_step, create: step, from: new_step}\n\n  - id: edit_step\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: step_edit\n          fields:\n            step:         {type: \"ref(step)\"}\n            title:        {type: string, trim: true, optional: true, check: \"size(value) > 0 && size(value) <= 255\"}\n            instructions: {type: string, trim: true, optional: true}\n            position:     {type: int, optional: true, check: \"value >= 0\"}\n      - gate:\n          id: not_frozen\n          refuse: 409\n          message: A walkthrough has already started on this challenge - the scenario is frozen\n          all: [\"size(walkthrough) == 0\"]\n      - act: {id: update_step, update: {resource: step_edit.step, from: step_edit}}\n\n  - id: remove_step\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: step_removal\n          fields:\n            step: {type: \"ref(step)\"}\n      - gate:\n          id: not_frozen\n          refuse: 409\n          message: A walkthrough has already started on this challenge - the scenario is frozen\n          all: [\"size(walkthrough) == 0\"]\n      - act: {id: delete_step, delete: step_removal.step}\n\n  # ── Validators ─────────────────────────────────────────────────────────\n  - id: open\n    entry:\n      trigger: user\n      access: {mode: signed_in}\n    nodes:\n      - collect:\n          id: start\n          fields:\n            app: {type: \"ref(app)\"}\n      - gate:\n          id: eligible_role\n          refuse: 403\n          message: Your role cannot walk through this scenario\n          all: [\"params.eligible_roles.exists(r, r == participation.role)\"]\n      - gate:\n          id: has_steps\n          refuse: 400\n          message: This challenge has no scenario step yet\n          all: [\"size(step) > 0\"]\n      - gate:\n          id: not_own_app\n          refuse: 403\n          message: You cannot walk through your own application\n          all: [\"start.app.contribution.author != participation.user\"]\n      - gate:\n          id: not_own_group\n          refuse: 403\n          message: You cannot walk through your own group's application\n          all: [\"!start.app.contribution.members.exists(m, m == participation.user)\"]\n      - act: {id: open_run, create: walkthrough, from: start, upsert: {by: [author, app]}}\n\n  - id: record\n    entry:\n      trigger: user\n      access: {mode: signed_in}\n    nodes:\n      - collect:\n          id: feedback\n          fields:\n            walkthrough:     {type: \"ref(walkthrough)\", where: \"walkthrough.author == participation.user && walkthrough.open\"}\n            step:            {type: \"ref(step)\"}\n            result:          {type: \"enum(passed, failed, blocked)\"}\n            comment:         {type: string, trim: true, optional: true}\n            medical_comment: {type: string, trim: true, optional: true}\n      - gate:\n          id: expert_only\n          refuse: 403\n          message: Only qualified experts can leave an expert opinion\n          all: [\"feedback.medical_comment == null || participation.qualified.expert_comment_qualification\"]\n      - act: {id: save_result, create: step_result, from: feedback, upsert: {by: [walkthrough, step], overwrite: true}}\n\n  - id: complete\n    entry:\n      trigger: user\n      access: {mode: signed_in}\n    nodes:\n      - collect:\n          id: finish\n          fields:\n            walkthrough:     {type: \"ref(walkthrough)\", where: \"walkthrough.author == participation.user && walkthrough.open\"}\n            global_feedback: {type: string, trim: true, check: \"size(value) > 0\"}\n      - gate:\n          id: eligible_role\n          refuse: 403\n          message: Your role cannot walk through this scenario\n          all: [\"params.eligible_roles.exists(r, r == participation.role)\"]\n      - gate:\n          id: not_own_app\n          refuse: 403\n          message: You cannot walk through your own application\n          all: [\"finish.walkthrough.app.contribution.author != participation.user\"]\n      - gate:\n          id: not_own_group\n          refuse: 403\n          message: You cannot walk through your own group's application\n          all: [\"!finish.walkthrough.app.contribution.members.exists(m, m == participation.user)\"]\n      - gate:\n          id: every_step_answered\n          refuse: 400\n          message: Some steps still have no result\n          reason: incomplete\n          all: [\"step.all(s, step_result.exists(r, r.walkthrough.id == finish.walkthrough.id && r.step.id == s.id))\"]\n      - act:\n          id: complete_run\n          transition:\n            resource: finish.walkthrough\n            to: closed\n            verdict: completed\n            resolution: {global_feedback: finish.global_feedback}\n      - reward:\n          id: pay\n          amount:   params.cp_per_validation\n          pool:     params.pool\n          clamp:    pool\n          rule_key: validation\n          meta:\n            targetContributionId: finish.walkthrough.app.contribution.id\n            runId: finish.walkthrough.id\n"
  },
  {
    "name": "ml",
    "origin": "installed",
    "yaml": "# The ML challenge as a template (template parity P5).\n#\n# Flipped with continuity: the challenges the hand-written flow (content/flows/ml)\n# served switch to this template as they are. The template keeps the flow's\n# data shapes — the step repos and their workspace_meta (userUrls, datasetUrls),\n# the dataset / model / api_packaging contributions, the same ledger keys and\n# meta — through the core `submissions` capability, and a sandbox promotion\n# keeps writing them as before.\n#\n# The rules of the hand-written flow, kept:\n# - four steps, each a repo created with the challenge (API optional); submitting\n#   a step's URL joins the challenge and scores it in the background;\n# - a URL belongs to whoever submitted it first; a reused dataset is not scored\n#   and pays nothing (skipped_reuse);\n# - dataset, model code and API packaging are graded by an AI grid; the model is\n#   paid by the metric its Kaggle card reports, normalized over the baseline,\n#   with a bonus for taking the lead from every other contributor;\n# - every payment is clamped to the pool in arrival order; a group's payment is\n#   multiplied by its bonus and split between members;\n# - the model step's payments credit the authors of the reused datasets\n#   (1/N of the selection each) and model, off pool, keeping min_keep_share;\n# - once the best metric reaches blockThreshold, dataset and model submissions close.\n#\n# The rules params keep the names reward_rules already stores.\n\nformat: leaderboardos/1\n\ntemplate:\n  id: ml\n  version: 1.0.0\n  name: ML\n  summary: >\n    Contributors submit a dataset, a model, its training code and an API, each\n    scored as it arrives and paid from the pool, with credit to the authors of\n    what they reuse.\n\nparams:\n  pool:    {type: points, mutable: false}\n  version: {type: int, default: 1, check: \"value == 1\", mutable: true}\n  dataset:\n    type: {cap: int}\n    check: \"value.cap >= 0\"\n    mutable: true\n  model:\n    type:\n      cap: int\n      kaggleShare: number\n      metric: {name: \"enum(auc, f1, accuracy)\", baseline: number, blockThreshold: \"optional(number)\"}\n      beatBestBonus: int\n    checks:\n      cap_is_positive: \"value.cap >= 0 && value.beatBestBonus >= 0\"\n      shares_are_ratios: \"value.kaggleShare >= 0 && value.kaggleShare <= 1 && value.metric.baseline >= 0 && value.metric.baseline <= 1\"\n    mutable: true\n  apiPackaging:\n    type: {cap: int}\n    check: \"value.cap >= 0\"\n    mutable: true\n  reuse:\n    type: {datasetShare: number, modelShare: number, minKeepShare: number}\n    check: \"value.datasetShare >= 0 && value.datasetShare <= 1 && value.modelShare >= 0 && value.modelShare <= 1 && value.minKeepShare >= 0 && value.minKeepShare <= 1\"\n    mutable: true\n\nrequires: {core: 1}\n\npresentation:\n  icon: brain\n  long_label: Machine learning\n  join_caption: Joining adds you to this challenge - you can then submit your dataset and model.\n  brief_required: true\n  public: true\n\nsubmissions:\n  selection: dataset\n  evaluation_handler: submission\n  closed_message: Metric threshold reached - dataset and model submissions are closed, only API packaging is accepted\n  steps:\n    dataset:\n      repo: kaggle_dataset\n      repo_title: Dataset\n      contribution: dataset\n      title: Dataset Submission\n      artifact: true\n      open: &open 'params.model.metric.blockThreshold == null || best(\"model_metric\", \"metricValue\") == null || best(\"model_metric\", \"metricValue\") < params.model.metric.blockThreshold'\n    model:\n      repo: kaggle_model\n      repo_title: Model\n      contribution: model\n      title: Model Submission\n      artifact: true\n      open: *open\n    model_code:\n      repo: github\n      repo_title: Model Code\n      contribution: model\n      title: Model Submission\n      open: *open\n    api:\n      repo: github\n      repo_title: API\n      contribution: api_packaging\n      title: API Packaging Submission\n      artifact: true\n      deliverables: [endpoint]\n      unless_input: api_packaging_enabled\n\nlanes:\n  - id: dataset\n    entry: {trigger: submission, step: dataset}\n    nodes:\n      # Réutiliser le dataset d'un autre ne rapporte rien : rien n'a été produit, rien n'est noté.\n      - gate:\n          id: not_reused\n          reason: skipped_reuse\n          all: [\"submission.lineage.artifacts.dataset == null\"]\n      - assess: {id: grade, kind: ai_grid, grid: '\"dataset\"', input: [submission.url], snapshot: latest}\n      - reward:\n          id: dataset_pay\n          rule_key: dataset\n          label: Dataset quality\n          amount: \"params.dataset.cap * grade.score\"\n          multiplier: participation.group.multiplier\n          pool: params.pool\n          clamp: pool\n          record_clamp: true\n          meta: {agentScore: grade.score}\n\n  - id: model\n    entry: {trigger: submission, step: model}\n    nodes:\n      - act: {id: card, capability: kaggle_metadata, url: submission.url}\n      - assess:\n          id: metric\n          kind: metric\n          value: \"card.metrics[params.model.metric.name]\"\n      - assess:\n          id: normalized\n          kind: metric\n          value: \"params.model.metric.baseline >= 1 ? 0.0 : max(0, min(1, (metric.value - params.model.metric.baseline) / (1 - params.model.metric.baseline)))\"\n      # Lu avant de payer : prendre la tête sur les autres, jamais se dépasser soi-même.\n      - assess:\n          id: lead\n          kind: metric\n          value: 'params.model.beatBestBonus > 0 && normalized.value > 0 && (best_of_others(\"model_metric\", \"metricValue\") == null || metric.value > best_of_others(\"model_metric\", \"metricValue\")) && !(best_of_mine(\"model_metric\", \"metricValue\") != null && (best_of_others(\"model_metric\", \"metricValue\") == null || best_of_mine(\"model_metric\", \"metricValue\") > best_of_others(\"model_metric\", \"metricValue\")))'\n      - assess:\n          id: previous_best\n          kind: metric\n          value: 'best_of_others(\"model_metric\", \"metricValue\")'\n      - reward:\n          id: metric_pay\n          rule_key: model_metric\n          label: Model metric\n          amount: \"params.model.cap * params.model.kaggleShare * normalized.value\"\n          multiplier: participation.group.multiplier\n          pool: params.pool\n          clamp: pool\n          record_clamp: true\n          meta: {metricValue: metric.value, normalizedMetric: normalized.value}\n          transfers: &reuse\n            floor: params.reuse.minKeepShare\n            to:\n              - rule_key: reuse_dataset\n                label: Dataset reuse\n                from: \"size(submission.lineage.selection) > 0 ? submission.lineage.selection : (submission.lineage.artifacts.dataset == null ? [] : [submission.lineage.artifacts.dataset])\"\n                share: params.reuse.datasetShare\n              - rule_key: reuse_model\n                label: Model reuse\n                from: \"submission.lineage.artifacts.model == null ? [] : [submission.lineage.artifacts.model]\"\n                share: params.reuse.modelShare\n      - gate:\n          id: takes_the_lead\n          branch:\n            - when: lead.value\n              nodes:\n                - reward:\n                    id: beat_best\n                    rule_key: beat_best\n                    label: Best model bonus\n                    amount: params.model.beatBestBonus\n                    multiplier: participation.group.multiplier\n                    pool: params.pool\n                    clamp: pool\n                    record_clamp: true\n                    meta: {metricValue: metric.value, previousBest: previous_best.value}\n                    transfers: *reuse\n            - else: {nodes: []}\n\n  - id: model_code\n    entry: {trigger: submission, step: model_code}\n    nodes:\n      - assess: {id: grade, kind: ai_grid, grid: '\"code\"', input: [submission.url], snapshot: latest}\n      - reward:\n          id: code_pay\n          rule_key: model_code\n          label: Model code\n          amount: \"params.model.cap * (1 - params.model.kaggleShare) * grade.score\"\n          multiplier: participation.group.multiplier\n          pool: params.pool\n          clamp: pool\n          record_clamp: true\n          meta: {agentScore: grade.score}\n          transfers: *reuse\n\n  - id: api\n    entry: {trigger: submission, step: api}\n    nodes:\n      - assess: {id: grade, kind: ai_grid, grid: '\"code\"', input: [submission.url], snapshot: latest}\n      - reward:\n          id: api_pay\n          rule_key: api_packaging\n          label: API packaging\n          amount: \"params.apiPackaging.cap * grade.score\"\n          multiplier: participation.group.multiplier\n          pool: params.pool\n          clamp: pool\n          record_clamp: true\n          meta: {agentScore: grade.score}\n"
  },
  {
    "name": "bug-bounty",
    "origin": "canonical",
    "yaml": "format: leaderboardos/1\n\ntemplate:\n  id: bug-bounty\n  version: 1.0.0\n  name: Bug bounty\n  summary: >\n    Anyone reports; a security lane triages under exclusive claim, routing\n    each report to a new vulnerability or an existing duplicate; only the\n    first reporter of a novel vulnerability is paid, by severity tier.\n\nparams:\n  pool:        {type: points, mutable: false}\n  triage_role: {type: role, mutable: false}\n  tiers:       {type: \"list({severity: enum(low, medium, high, critical), points: points})\", mutable: true}\n\nrequires: {core: 1}\n\nresources:\n  report:\n    fields:\n      description: {type: string, visibility: [author, \"role(params.triage_role)\"]}\n      poc:         {type: file,   visibility: [author, \"role(params.triage_role)\"]}\n    created_by: [reporter.register, intake.register]\n    claim: {mode: exclusive, ttl: 72h}\n    closure: {by: transition, verdict: [novel, duplicate, invalid]}\n  vulnerability:\n    fields:\n      title:    {type: string, visibility: [\"role(params.triage_role)\", admin]}\n      severity: {type: \"enum(low, medium, high, critical)\", visibility: [\"role(params.triage_role)\", admin]}\n    match_or_create: {by: human}\n\nlanes:\n  - id: reporter\n    entry: {trigger: user, access: {mode: open}}\n    nodes:\n      - collect: {id: file_report, fields: {description: {type: string}, poc: {type: file}}}\n      - act: {id: register, create: report, from: file_report}\n\n  - id: intake\n    entry: {trigger: webhook, dedup: {by: external_id, window: 30d}}\n    nodes:\n      - act: {id: register, create: report, from: webhook.payload}\n\n  - id: triage\n    entry: {trigger: user, access: {mode: role, role: params.triage_role}}\n    nodes:\n      - act: {id: take, claim: {resource: report}}\n      - collect:\n          id: decide\n          fields:\n            outcome:  {type: \"enum(novel, duplicate, invalid)\"}\n            existing: {type: \"ref(vulnerability)\", when: 'outcome == \"duplicate\"'}\n            severity: {type: \"enum(low, medium, high, critical)\", when: 'outcome == \"novel\"'}\n      - act:\n          id: route\n          match_or_create: {resource: vulnerability, decision: decide}\n          attach: take.report\n      - act: {id: settle, transition: {resource: take.report, to: closed, verdict: decide.outcome}}\n      - gate: {id: novel_only, all: ['decide.outcome == \"novel\"']}\n      - reward:\n          id: bounty\n          to: take.report.author\n          amount: {mapping: tiers, tiers: params.tiers, key: severity, match: equals, input: decide.severity}\n          pool: params.pool\n"
  },
  {
    "name": "data-annotation",
    "origin": "canonical",
    "yaml": "format: leaderboardos/1\n\ntemplate:\n  id: data-annotation\n  version: 1.0.0\n  name: Data annotation with gold cases\n  summary: >\n    Annotators label items under k-redundancy; hidden gold cases maintain a\n    per-annotator accuracy record that weights pay and gates sensitive\n    work; items resolve by agreement; payment is fast, audited by sampled\n    clawback.\n\nparams:\n  pool:       {type: points, mutable: false}\n  per_unit:   {type: points, mutable: true}\n  redundancy: {type: int, mutable: false}\n  gold_rate:  {type: ratio, mutable: true}\n  clearance:  {type: {min_seen: int, min_accuracy: ratio}, mutable: true}\n  audit_rate: {type: ratio, mutable: true}\n\nrequires: {core: 1}\n\nresources:\n  item:\n    fields:\n      payload: {type: json, visibility: [claimant, admin]}\n      class:   {type: \"enum(standard, sensitive)\"}\n    created_by: [import.explode_items]\n    claim: {mode: k_bounded, k: params.redundancy, ttl: 48h}\n    closure: {by: aggregate, verdict: [labeled]}\n  gold:\n    fields:\n      payload:  {type: json, visibility: [claimant, admin]}\n      expected: {type: json, visibility: []}\n    created_by: [import.explode_golds]\n    claim: {mode: unique_per, dimensions: [self, participation]}\n\ncounters:\n  gold_seen:    {type: int}\n  gold_correct: {type: int}\n\nlifecycle:\n  aggregates:\n    - id: agreement\n      over: item\n      per_participation: 1\n      resolve:\n        when:    \"count(inputs) == params.redundancy\"\n        verdict: \"mode(inputs.map(i, i.value))\"\n        then:\n          - transition: {resource: item, to: closed, verdict: labeled}\n\nlanes:\n  - id: import\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: batch\n          fields:\n            file:  {type: file}\n            kind:  {type: \"enum(items, golds)\"}\n            class: {type: \"enum(standard, sensitive)\"}\n      - gate:\n          id: kind\n          branch:\n            - when: 'batch.kind == \"golds\"'\n              nodes:\n                - act: {id: explode_golds, create: gold, many: {from_file: batch.file}}\n            - else:\n                nodes:\n                  - act: {id: explode_items, create: item, many: {from_file: batch.file}, set: {class: batch.class}}\n\n  - id: annotator\n    entry: {trigger: user, access: {mode: open}}\n    nodes:\n      - act:\n          id: draw\n          claim:\n            resource: item\n            where: >\n              item.class == \"standard\"\n              || (counters.gold_seen >= params.clearance.min_seen\n                  && counters.gold_correct\n                     >= params.clearance.min_accuracy * counters.gold_seen)\n            substitute: {resource: gold, rate: params.gold_rate}\n      - collect: {id: label, fields: {value: {type: json}}}\n      - gate:\n          id: kind\n          branch:\n            - when: \"draw.substituted\"\n              nodes:\n                - assess:\n                    id: check\n                    kind: metric\n                    value: \"label.value == draw.gold.expected\"\n                    counters:\n                      gold_seen:    {add: \"1\"}\n                      gold_correct: {add: \"value ? 1 : 0\"}\n            - else:\n                nodes:\n                  - assess:\n                      id: submit\n                      kind: human\n                      from: label\n                      emit: {to: lifecycle.agreement, scope: draw.item}\n      - reward:\n          id: pay\n          amount: >\n            params.per_unit\n            * (counters.gold_seen == 0 ? 1.0\n               : counters.gold_correct * 1.0 / counters.gold_seen)\n          pool: params.pool\n\n  - id: audit\n    entry:\n      trigger: cron\n      schedule: weekly\n      over: {resource: item, where: \"item.closed\", sample: params.audit_rate}\n      cursor: engine\n    nodes:\n      - assess:\n          id: recheck\n          kind: metric\n          value: \"aggregates.agreement.inputs.filter(i, i.value != aggregates.agreement.verdict)\"\n      - reward:\n          id: clawback\n          to: recheck.value\n          amount: \"-params.per_unit\"\n          rule_key: clawback\n          pool: params.pool\n"
  },
  {
    "name": "design-contest",
    "origin": "canonical",
    "yaml": "format: leaderboardos/1\n\ntemplate:\n  id: design-contest\n  version: 1.0.0\n  name: Design contest\n  summary: >\n    Open submissions during the window; at closure a jury aggregate ranks\n    entries and the podium is paid by rank.\n\nparams:\n  pool:       {type: points, mutable: false}\n  close_date: {type: date, mutable: true}\n  podium:     {type: \"list(points)\", mutable: false}\n  jury_role:  {type: role, mutable: false}\n\nrequires: {core: 1}\n\nresources:\n  entry:\n    fields:\n      asset:     {type: file, visibility: [author, \"role(params.jury_role)\", admin]}\n      statement: {type: string}\n    created_by: [contributor.register]\n    closure: {by: transition}\n\nlifecycle:\n  states: {close_at: params.close_date}\n  aggregates:\n    - id: panel\n      over: entry\n      per_participation: 1\n      resolve:\n        when:    'challenge.state == \"closed\"'\n        verdict: \"mean(inputs.map(i, i.score))\"\n  on_close:\n    - reward:\n        id: podium_pay\n        amount: {mapping: rank, over: entry, by: aggregates.panel.verdict, order: desc, amounts: params.podium}\n        pool: params.pool\n\nlanes:\n  - id: contributor\n    entry: {trigger: user, access: {mode: open}}\n    nodes:\n      - collect: {id: submit, fields: {asset: {type: file}, statement: {type: string}}}\n      - act: {id: register, create: entry, from: submit}\n\n  - id: jury\n    entry: {trigger: user, access: {mode: role, role: params.jury_role}}\n    nodes:\n      - collect: {id: pick, fields: {entry: {type: \"ref(entry)\"}}}\n      - gate: {id: not_own, all: [\"pick.entry.author != participation.user\"]}\n      - assess:\n          id: score\n          kind: human\n          fields: {score: {type: number, check: \"value >= 0.0 && value <= 9.0\"}}\n          emit: {to: lifecycle.panel, scope: pick.entry}\n"
  },
  {
    "name": "developer-onboarding",
    "origin": "canonical",
    "yaml": "format: leaderboardos/1\n\ntemplate:\n  id: developer-onboarding\n  version: 1.0.0\n  name: Developer onboarding\n  summary: >\n    A single long run: each step gives an instruction, verifies on a\n    third-party API that it really happened, and pays a micro-reward.\n\nparams:\n  pool:        {type: points, mutable: false}\n  repo:        {type: url, mutable: false}\n  step_points: {type: \"list(points)\", mutable: true}\n\nrequires: {core: 1}\n\nresources: {}\n\nlanes:\n  - id: dev\n    entry:\n      trigger: user\n      access: {mode: open, runs_per_participation: 1}\n    nodes:\n      - collect: {id: identity, fields: {github_handle: {type: string}}}\n      - act:\n          id: v_fork\n          kind: observer\n          capability: github_check\n          check: fork_exists\n          of: params.repo\n          by: identity.github_handle\n      - gate:   {id: g1, all: [\"v_fork.ok\"]}\n      - reward: {id: r1, amount: \"params.step_points[0]\", pool: params.pool}\n      - collect: {id: pr, fields: {url: {type: url}}}\n      - act:\n          id: v_pr\n          kind: observer\n          capability: github_check\n          check: pr_open\n          url: pr.url\n          by: identity.github_handle\n      - gate:   {id: g2, all: [\"v_pr.ok\"]}\n      - reward: {id: r2, amount: \"params.step_points[1]\", pool: params.pool}\n      - collect: {id: deploy, fields: {endpoint: {type: url}}}\n      - act:    {id: v_live, kind: observer, capability: http_proxy, to: deploy.endpoint}\n      - gate:   {id: g3, all: [\"v_live.status == 200\"]}\n      - reward: {id: r3, amount: \"params.step_points[2]\", pool: params.pool}\n"
  },
  {
    "name": "endpoint-validation",
    "origin": "canonical",
    "yaml": "format: leaderboardos/1\n\ntemplate:\n  id: endpoint-validation\n  version: 1.0.0\n  name: Endpoint validation\n  summary: >\n    Qualified reviewers verify deployed submissions from a source challenge\n    against peer-authored ground-truth cases, under quorum.\n\nparams:\n  pool:                 {type: points, mutable: false}\n  cp_per_validation:    {type: points, mutable: false}\n  required_validations: {type: int, check: \"value % 2 == 1\", mutable: false}\n  source_challenge:     {type: challenge_ref, mutable: false}\n  reviewer_role:        {type: role, mutable: false}\n\nrequires: {core: 1}\n\nresources:\n  target:\n    fields:\n      contribution:  {type: link, from: params.source_challenge}\n      endpoint_url:  {type: url, visibility: [admin, \"role(params.reviewer_role)\"]}\n    created_by: [admin.create_target]\n    closure: {by: aggregate, verdict: [works, broken], permanent: true}\n\n  reference_case:\n    fields:\n      input:            {type: file, visibility: [author, admin]}\n      expected_output:  {type: file, visibility: []}\n    created_by: [author.create_case]\n    cardinality: {exactly: params.required_validations}\n    claim:\n      mode: unique_per\n      dimensions: [self, target]\n\nlifecycle:\n  states: standard\n  aggregates:\n    - id: quorum\n      over: target\n      per_participation: 1\n      resolve:\n        when:    \"count(inputs) == params.required_validations\"\n        verdict: \"majority(inputs.map(i, i.verdict))\"\n        then:\n          - transition: {resource: target, to: closed}\n          - reward:\n              to:     \"inputs.filter(i, i.verdict == verdict)\"\n              amount: params.cp_per_validation\n              pool:   params.pool\n              order:  commit_time\n              clamp:  pool\n      state_visibility:\n        count: everyone\n        split: admin\n\nlanes:\n  - id: admin\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: expose\n          fields:\n            contribution: {type: link, from: params.source_challenge}\n            endpoint_url: {type: url}\n      - act: {id: create_target, create: target, from: expose}\n\n  - id: author\n    entry:\n      trigger: user\n      access: {mode: role, role: params.reviewer_role}\n    nodes:\n      - collect:\n          id: submit_case\n          fields:\n            input:           {type: file}\n            expected_output: {type: file}\n      - act: {id: create_case, create: reference_case, from: submit_case}\n\n  - id: reviewer\n    entry:\n      trigger: user\n      access: {mode: role, role: params.reviewer_role}\n    nodes:\n      - collect:\n          id: pick\n          fields:\n            target: {type: \"ref(target)\", where: \"target.open\"}\n            case:   {type: \"ref(reference_case)\"}\n      - gate:\n          id: eligibility\n          all:\n            - \"pick.case.author != participation.user\"\n            - \"pick.target.contribution.author != participation.user\"\n      - act:\n          id: probe\n          kind: observer\n          claim: {resource: pick.case, scope: {target: pick.target}}\n          capability: http_proxy\n          send:  pick.case.input\n          to:    pick.target.endpoint_url\n          store: response\n      - collect:\n          id: observation\n          fields: {text: {type: string}}\n      - act:\n          id: reveal\n          kind: grant\n          grant: {field: pick.case.expected_output, to: participation}\n      - assess:\n          id: verdict\n          kind: human\n          fields:\n            verdict:     {type: \"enum(works, broken)\"}\n            description: {type: string}\n          emit: {to: lifecycle.quorum, scope: pick.target}\n"
  },
  {
    "name": "graded-submission",
    "origin": "canonical",
    "yaml": "format: leaderboardos/1\n\ntemplate:\n  id: graded-submission\n  version: 1.0.0\n  name: Graded submission challenge\n  summary: >\n    Typed artifacts, self-triggered AI evaluation, pool-draining rewards,\n    optional group participation.\n\nparams:\n  pool:      {type: points, mutable: false}\n  rate:      {type: number, mutable: true}\n  min_score: {type: number, mutable: true}\n  kinds:\n    type: \"list({kind: string, connector: capability, grid: grid_ref})\"\n    mutable: false\n  group:\n    type: {max_size: int, multiplier: expr}\n    mutable: false\n\nrequires: {core: 1}\n\nresources:\n  contribution:\n    fields:\n      kind:     {type: string}\n      url:      {type: url}\n      metadata: {type: json,   visibility: [author, admin]}\n      score:    {type: number, visibility: [author, admin]}\n    created_by: [contributor.register]\n\nlanes:\n  - id: contributor\n    entry:\n      trigger: user\n      access: {mode: open, group: params.group}\n    nodes:\n      - collect:\n          id: submit\n          fields:\n            kind: {type: \"enum(params.kinds.map(k, k.kind))\"}\n            url:  {type: url}\n      - act:\n          id: fetch\n          kind: observer\n          capability: \"params.kinds.filter(k, k.kind == submit.kind)[0].connector\"\n          url: submit.url\n          store: metadata\n      - act: {id: register, create: contribution, from: [submit, fetch]}\n      - assess:\n          id: grade\n          kind: ai_grid\n          grid: \"params.kinds.filter(k, k.kind == submit.kind)[0].grid\"\n          input: [submit.url, fetch.metadata]\n      - gate: {id: floor, all: [\"grade.score >= params.min_score\"]}\n      - reward:\n          id: pay\n          amount: >\n            params.rate * grade.score\n            * (1.0 + 0.3 * (size(group.members) - 1.0))\n          pool: params.pool\n          clamp: pool\n"
  },
  {
    "name": "journey-validation",
    "origin": "canonical",
    "yaml": "format: leaderboardos/1\n\ntemplate:\n  id: journey-validation\n  version: 1.0.0\n  name: Journey validation\n  summary: >\n    Qualified reviewers walk a deployed application through an ordered\n    user journey, one verdict per step; a journey verdict per reviewer\n    resolves under quorum, majority side paid.\n\nparams:\n  pool:             {type: points, mutable: false}\n  cp_per_journey:   {type: points, mutable: false}\n  quorum:           {type: int, check: \"value % 2 == 1\", mutable: false}\n  source_challenge: {type: challenge_ref, mutable: false}\n  reviewer_role:    {type: role, mutable: false}\n\nrequires: {core: 1}\n\nresources:\n  target:\n    fields:\n      contribution: {type: link, from: params.source_challenge}\n      app_url:      {type: url, visibility: [admin, \"role(params.reviewer_role)\"]}\n    created_by: [expose.create_target]\n    closure: {by: aggregate, verdict: [works, broken], permanent: true}\n\n  journey_step:\n    fields:\n      order:       {type: int}\n      instruction: {type: string}\n    created_by: [journey.create_step]\n    claim:\n      mode: unique_per\n      dimensions: [self, target, participation]\n\n  step_report:\n    fields:\n      target:  {type: \"ref(target)\"}\n      step:    {type: \"ref(journey_step)\"}\n      outcome: {type: \"enum(passed, failed)\", visibility: [author, admin]}\n      note:    {type: string, visibility: [author, admin]}\n    created_by: [reviewer.log]\n\nlifecycle:\n  states: standard\n  aggregates:\n    - id: journey\n      over: target\n      per_participation: 1\n      resolve:\n        when:    \"count(inputs) == params.quorum\"\n        verdict: \"majority(inputs.map(i, i.value))\"\n        then:\n          - transition: {resource: target, to: closed}\n          - reward:\n              to:     \"inputs.filter(i, i.value == verdict)\"\n              amount: params.cp_per_journey\n              pool:   params.pool\n              order:  commit_time\n              clamp:  pool\n      state_visibility:\n        count: everyone\n        split: admin\n\nlanes:\n  - id: journey\n    entry: {trigger: admin}\n    nodes:\n      - collect: {id: define, fields: {order: {type: int}, instruction: {type: string}}}\n      - act: {id: create_step, create: journey_step, from: define}\n\n  - id: expose\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: expose_app\n          fields:\n            contribution: {type: link, from: params.source_challenge}\n            app_url:      {type: url}\n      - act: {id: create_target, create: target, from: expose_app}\n\n  - id: reviewer\n    entry:\n      trigger: user\n      access: {mode: role, role: params.reviewer_role}\n    nodes:\n      - collect:\n          id: pick_target\n          fields:\n            target: {type: \"ref(target)\", where: \"target.open\"}\n      - gate:\n          id: not_own\n          all: [\"pick_target.target.contribution.author != participation.user\"]\n      - collect:\n          id: pick_step\n          fields:\n            step:\n              type: \"ref(journey_step)\"\n              where: >\n                step.order == 1\n                || exists(step_report, r,\n                     r.author == participation.user\n                     && r.target == pick_target.target\n                     && r.step.order == step.order - 1\n                     && r.outcome == \"passed\")\n      - assess:\n          id: judge\n          kind: human\n          claim: {resource: pick_step.step, scope: {target: pick_target.target}}\n          fields:\n            outcome: {type: \"enum(passed, failed)\"}\n            note:    {type: string}\n      - act: {id: log, create: step_report, from: [pick_target, pick_step, judge]}\n      - gate:\n          id: result\n          branch:\n            - when: 'judge.outcome == \"failed\"'\n              nodes:\n                - assess:\n                    id: cast_broken\n                    kind: metric\n                    value: '\"broken\"'\n                    emit: {to: lifecycle.journey, scope: pick_target.target}\n            - when: \"!exists(journey_step, s, s.order > pick_step.step.order)\"\n              nodes:\n                - assess:\n                    id: cast_works\n                    kind: metric\n                    value: '\"works\"'\n                    emit: {to: lifecycle.journey, scope: pick_target.target}\n            - else: {nodes: []}\n"
  },
  {
    "name": "localization",
    "origin": "canonical",
    "yaml": "format: leaderboardos/1\n\ntemplate:\n  id: localization\n  version: 1.0.0\n  name: Localization pipeline\n  summary: >\n    Translators claim source strings exclusively; native reviewers approve\n    or reject; approval pays the translator per string.\n\nparams:\n  pool:          {type: points, mutable: false}\n  per_string:    {type: points, mutable: true}\n  reviewer_role: {type: role, mutable: false}\n  target_locale: {type: string, mutable: false}\n\nrequires: {core: 1}\n\nresources:\n  string:\n    fields:\n      key:     {type: string}\n      source:  {type: string}\n      context: {type: string}\n    created_by: [import.explode]\n    claim:\n      mode: exclusive\n      ttl: 72h\n      where: \"count(translation.filter(t, t.open && t.string == self)) == 0\"\n    closure: {by: transition, verdict: [translated]}\n  translation:\n    fields:\n      string: {type: \"ref(string)\"}\n      text:   {type: string}\n    created_by: [translator.register]\n    claim: {mode: exclusive, ttl: 72h}\n    closure: {by: transition, verdict: [approved, rejected]}\n\nlanes:\n  - id: import\n    entry: {trigger: admin}\n    nodes:\n      - collect: {id: batch, fields: {file: {type: file}}}\n      - act: {id: explode, create: string, many: {from_file: batch.file}}\n\n  - id: translator\n    entry: {trigger: user, access: {mode: open}}\n    nodes:\n      - act: {id: take, claim: {resource: string}}\n      - collect: {id: submit, fields: {text: {type: string}}}\n      - act: {id: register, create: translation, from: submit, set: {string: take.string}}\n\n  - id: review\n    entry: {trigger: user, access: {mode: role, role: params.reviewer_role}}\n    nodes:\n      - act: {id: take, claim: {resource: translation}}\n      - gate: {id: not_own, all: [\"take.translation.author != participation.user\"]}\n      - assess:\n          id: judge\n          kind: human\n          fields:\n            decision: {type: \"enum(approved, rejected)\"}\n            note:     {type: string}\n      - gate:\n          id: route\n          branch:\n            - when: 'judge.decision == \"approved\"'\n              nodes:\n                - act: {id: close_t, transition: {resource: take.translation, to: closed, verdict: approved}}\n                - act: {id: close_s, transition: {resource: take.translation.string, to: closed, verdict: translated}}\n                - reward: {id: pay, to: take.translation.author, amount: params.per_string, pool: params.pool}\n            - else:\n                nodes:\n                  - act: {id: reject, transition: {resource: take.translation, to: closed, verdict: rejected}}\n"
  },
  {
    "name": "sandbox-project",
    "origin": "canonical",
    "yaml": "format: leaderboardos/1\n\ntemplate:\n  id: sandbox-project\n  version: 1.0.0\n  name: Sandbox project\n  summary: >\n    A contributor proposes and works on their own project. Admin-defined\n    star-tier milestones pay from the pool; self-evaluation is formative;\n    promotion spawns an official challenge and auto-joins the author.\n\nparams:\n  pool:                {type: points, mutable: false}\n  promotion_templates: {type: \"list(template_ref)\", mutable: false}\n  self_grids:          {type: {code: grid_ref, ml: grid_ref}, mutable: false}\n\nrequires: {core: 1}\n\nresources:\n  project:\n    fields:\n      title:       {type: string}\n      kind:        {type: \"enum(code, ml)\"}\n      description: {type: string}\n      repo_url:    {type: url}\n    created_by: [creator.open_project]\n    closure: {by: [admin_act, transition], verdict: [promoted, archived]}\n  milestone:\n    fields:\n      project:  {type: \"ref(project)\"}\n      tier:     {type: int}\n      criteria: {type: string}\n      points:   {type: points}\n    created_by: [milestones.create_tier]\n    closure: {by: admin_act, verdict: [reached]}\n\nlanes:\n  - id: creator\n    entry: {trigger: user, access: {mode: open}}\n    nodes:\n      - collect:\n          id: propose\n          fields:\n            title:       {type: string}\n            kind:        {type: \"enum(code, ml)\"}\n            description: {type: string}\n            repo_url:    {type: url}\n      - act: {id: open_project, create: project, from: propose}\n\n  - id: self_review\n    entry: {trigger: user, access: {mode: author_of, resource: project}}\n    nodes:\n      - assess:\n          id: formative\n          kind: self\n          grid: \"params.self_grids[project.kind]\"\n          gating: false\n\n  - id: milestones\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: define\n          fields:\n            project:  {type: \"ref(project)\"}\n            tier:     {type: int}\n            criteria: {type: string}\n            points:   {type: points}\n      - act: {id: create_tier, create: milestone, from: define}\n\n  - id: award\n    entry: {trigger: admin}\n    nodes:\n      - collect: {id: review, fields: {milestone: {type: \"ref(milestone)\", where: \"milestone.open\"}}}\n      - act: {id: settle, transition: {resource: review.milestone, to: closed, verdict: reached}}\n      - reward:\n          id: tier_pay\n          to: review.milestone.project.author\n          amount: review.milestone.points\n          pool: params.pool\n\n  - id: promote\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: pick\n          fields:\n            project:         {type: \"ref(project)\", where: \"project.open\"}\n            template:        {type: \"enum(params.promotion_templates)\"}\n            instance_params: {type: json}\n      - act:\n          id: spawn\n          kind: effector\n          capability: spawn_challenge\n          template: pick.template\n          params: pick.instance_params\n          auto_join: pick.project.author\n      - act: {id: close, transition: {resource: pick.project, to: closed, verdict: promoted}}\n"
  },
  {
    "name": "social-amplification",
    "origin": "canonical",
    "yaml": "format: leaderboardos/1\n\ntemplate:\n  id: social-amplification\n  version: 1.0.0\n  name: Social amplification\n  summary: >\n    Contributors publish on shared brand accounts and declare their posts;\n    the engine verifies the account, waits out a maturation window,\n    measures engagement, and pays by tier.\n\nparams:\n  pool:            {type: points, mutable: false}\n  platforms:       {type: \"list(enum(instagram, x, linkedin))\", mutable: false}\n  maturation_days: {type: int, mutable: true}\n  tiers:           {type: \"list({min_engagement: number, points: points})\", mutable: true}\n\nrequires: {core: 1}\n\nresources:\n  account:\n    fields:\n      platform: {type: \"enum(params.platforms)\"}\n      handle:   {type: string}\n      notes:    {type: string, visibility: [admin]}\n    created_by: [accounts.create_account]\n    claim: {mode: unbounded}\n  post:\n    fields:\n      url:     {type: url}\n      account: {type: \"ref(account)\"}\n      metrics: {type: json, visibility: [author, admin]}\n    created_by: [contributor.register]\n    match_or_create: {by: url}\n    closure: {by: transition, verdict: [measured]}\n\nlanes:\n  - id: accounts\n    entry: {trigger: admin}\n    nodes:\n      - collect:\n          id: register_account\n          fields:\n            platform: {type: \"enum(params.platforms)\"}\n            handle:   {type: string}\n      - act: {id: create_account, create: account, from: register_account}\n\n  - id: contributor\n    entry: {trigger: user, access: {mode: open}}\n    nodes:\n      - collect: {id: declare, fields: {url: {type: url}}}\n      - act:\n          id: resolve\n          kind: observer\n          capability: social_metadata\n          url: declare.url\n          store: meta\n      - gate:\n          id: ours\n          all:\n            - \"exists(account, a, a.platform == resolve.meta.platform && a.handle == resolve.meta.handle)\"\n      - act:\n          id: register\n          create: post\n          from: declare\n          set:\n            account: \"account.filter(a, a.platform == resolve.meta.platform && a.handle == resolve.meta.handle)[0]\"\n\n  - id: measure\n    entry:\n      trigger: cron\n      schedule: daily\n      over: {resource: post, where: \"post.open && age(post) >= params.maturation_days\"}\n      cursor: engine\n    nodes:\n      - act: {id: fetch, kind: observer, capability: social_metadata, url: post.url, store: metrics}\n      - assess: {id: reach, kind: metric, value: fetch.metrics.engagement}\n      - reward:\n          id: tier_pay\n          to: post.author\n          amount: {mapping: tiers, tiers: params.tiers, key: min_engagement, match: at_least, input: reach.value}\n          pool: params.pool\n      - act: {id: settle, transition: {resource: post, to: closed, verdict: measured}}\n"
  },
  {
    "name": "staked-grant-review",
    "origin": "canonical",
    "yaml": "format: leaderboardos/1\n\ntemplate:\n  id: staked-grant-review\n  version: 1.0.0\n  name: Staked grant review\n  summary: >\n    Reviewers stake points to enter; each application is reviewed by k\n    reviewers; consensus pays the aligned and slashes the deviant, bounded\n    by their stake; remaining stake is refunded at challenge close.\n\nparams:\n  pool:       {type: points, mutable: false}\n  stake:      {type: points, mutable: false}\n  redundancy: {type: int, mutable: false}\n  per_review: {type: points, mutable: true}\n  slash:      {type: points, mutable: true}\n\nrequires: {core: 1}\n\nresources:\n  application:\n    fields:\n      title:    {type: string}\n      document: {type: file}\n    created_by: [intake.register]\n    claim: {mode: k_bounded, k: params.redundancy, ttl: 96h}\n    closure: {by: aggregate, verdict: [fund, reject]}\n\ncounters:\n  slashed: {type: points}\n\nlifecycle:\n  aggregates:\n    - id: consensus\n      over: application\n      per_participation: 1\n      resolve:\n        when:    \"count(inputs) == params.redundancy\"\n        verdict: \"majority(inputs.map(i, i.recommendation))\"\n        then:\n          - transition: {resource: application, to: closed}\n          - reward:\n              to:     \"inputs.filter(i, i.recommendation == verdict)\"\n              amount: params.per_review\n              pool:   params.pool\n          - counters:\n              on: \"inputs.filter(i, i.recommendation != verdict)\"\n              update:\n                slashed: {add: \"min(params.slash, params.stake - counters.slashed)\"}\n  on_close:\n    - reward:\n        id: refund\n        to: each_participation\n        amount: \"params.stake - counters.slashed\"\n        rule_key: stake_refund\n\nlanes:\n  - id: intake\n    entry: {trigger: admin}\n    nodes:\n      - collect: {id: register_app, fields: {title: {type: string}, document: {type: file}}}\n      - act: {id: register, create: application, from: register_app}\n\n  - id: reviewer\n    entry:\n      trigger: user\n      access:\n        mode: open\n        stake: {amount: params.stake}\n    nodes:\n      - act: {id: take, claim: {resource: application}}\n      - collect:\n          id: review\n          fields:\n            recommendation: {type: \"enum(fund, reject)\"}\n            score:          {type: number}\n            rationale:      {type: string, visibility: [admin]}\n      - assess:\n          id: cast\n          kind: human\n          from: review\n          emit: {to: lifecycle.consensus, scope: take.application}\n"
  }
];
